57	/**
58	 * A SandboxManager implementation for Windows that uses Restricted Tokens,
59	 * Job Objects, and Low Integrity levels for process isolation.
60	 * Uses a native C# helper to bypass PowerShell restrictions.
61	 */
62	export class WindowsSandboxManager implements SandboxManager {
63	  static readonly HELPER_EXE = 'GeminiSandbox.exe';
64	  private readonly helperPath: string;
65	  private initialized = false;
66	  private readonly allowedCache = new Set<string>();
67	  private readonly deniedCache = new Set<string>();
68	  private readonly denialCache: SandboxDenialCache = createSandboxDenialCache();
69	
70	  constructor(private readonly options: GlobalSandboxOptions) {
71	    this.helperPath = path.resolve(__dirname, WindowsSandboxManager.HELPER_EXE);
72	  }
73	
74	  isKnownSafeCommand(args: string[]): boolean {
75	    const toolName = args[0]?.toLowerCase();
76	    const approvedTools = this.options.modeConfig?.approvedTools ?? [];
77	    if (toolName && approvedTools.some((t) => t.toLowerCase() === toolName)) {
78	      return true;
79	    }
80	    return isKnownSafeCommand(args);
81	  }
82	
83	  isDangerousCommand(args: string[]): boolean {
84	    return isDangerousCommand(args);
85	  }
86	
87	  parseDenials(result: ShellExecutionResult): ParsedSandboxDenial | undefined {
88	    return parseWindowsSandboxDenials(result, this.denialCache);
89	  }
90	
91	  getWorkspace(): string {
92	    return this.options.workspace;
93	  }
94	
95	  getOptions(): GlobalSandboxOptions {
96	    return this.options;
97	  }
