99	  /**
100	   * Ensures a file or directory exists.
101	   */
102	  private touch(filePath: string, isDirectory: boolean): void {
103	    assertValidPathString(filePath);
104	    try {
105	      // If it exists (even as a broken symlink), do nothing
106	      if (fs.lstatSync(filePath)) return;
107	    } catch {
108	      // Ignore ENOENT
109	    }
110	
111	    if (isDirectory) {
112	      fs.mkdirSync(filePath, { recursive: true });
113	    } else {
114	      const dir = path.dirname(filePath);
115	      if (!fs.existsSync(dir)) {
116	        fs.mkdirSync(dir, { recursive: true });
117	      }
118	      fs.closeSync(fs.openSync(filePath, 'a'));
119	    }
120	  }
