122	  private async ensureInitialized(): Promise<void> {
123	    if (this.initialized) return;
124	    if (os.platform() !== 'win32') {
125	      this.initialized = true;
126	      return;
127	    }
128	
129	    try {
130	      if (!fs.existsSync(this.helperPath)) {
131	        debugLogger.log(
132	          `WindowsSandboxManager: Helper not found at ${this.helperPath}. Attempting to compile...`,
133	        );
134	        // If the exe doesn't exist, we try to compile it from the .cs file
135	        const sourcePath = this.helperPath.replace(/\.exe$/, '.cs');
136	        if (fs.existsSync(sourcePath)) {
137	          const systemRoot = process.env['SystemRoot'] || 'C:\\Windows';
138	          const cscPaths = [
139	            'csc.exe', // Try in PATH first
140	            path.join(
141	              systemRoot,
142	              'Microsoft.NET',
143	              'Framework64',
144	              'v4.0.30319',
145	              'csc.exe',
146	            ),
147	            path.join(
148	              systemRoot,
149	              'Microsoft.NET',
150	              'Framework',
151	              'v4.0.30319',
152	              'csc.exe',
153	            ),
154	            // Added newer framework paths
155	            path.join(
156	              systemRoot,
157	              'Microsoft.NET',
158	              'Framework64',
159	              'v4.8',
160	              'csc.exe',
161	            ),
162	            path.join(
163	              systemRoot,
164	              'Microsoft.NET',
165	              'Framework',
166	              'v4.8',
167	              'csc.exe',
168	            ),
169	            path.join(
170	              systemRoot,
171	              'Microsoft.NET',
172	              'Framework64',
173	              'v3.5',
174	              'csc.exe',
175	            ),
176	          ];
177	
178	          let compiled = false;
179	          for (const csc of cscPaths) {
180	            try {
181	              debugLogger.log(
182	                `WindowsSandboxManager: Trying to compile using ${csc}...`,
183	              );
184	              // We use spawnAsync but we don't need to capture output
185	              await spawnAsync(csc, ['/out:' + this.helperPath, sourcePath]);
186	              debugLogger.log(
187	                `WindowsSandboxManager: Successfully compiled sandbox helper at ${this.helperPath}`,
188	              );
189	              compiled = true;
190	              break;
191	            } catch (e) {
192	              debugLogger.log(
193	                `WindowsSandboxManager: Failed to compile using ${csc}: ${e instanceof Error ? e.message : String(e)}`,
194	              );
195	            }
196	          }
197	
198	          if (!compiled) {
199	            debugLogger.log(
200	              'WindowsSandboxManager: Failed to compile sandbox helper from any known CSC path.',
201	            );
202	          }
203	        } else {
204	          debugLogger.log(
205	            `WindowsSandboxManager: Source file not found at ${sourcePath}. Cannot compile helper.`,
206	          );
207	        }
208	      } else {
209	        debugLogger.log(
210	          `WindowsSandboxManager: Found helper at ${this.helperPath}`,
211	        );
212	      }
213	    } catch (e) {
214	      debugLogger.log(
215	        'WindowsSandboxManager: Failed to initialize sandbox helper:',
216	        e,
217	      );
218	    }
219	
220	    this.initialized = true;
221	  }
